"""Dhan: the access token (generated by PIN + TOTP), and the HTTP client every job uses.

The token is never printed or logged. It is kept in state/dhan_token.json (owner-only on Linux).
"""
import datetime as dt
import json
import os
import threading
import time

import pyotp
import requests

from .config import ENV, IST, STATE, S, client_id, need

AUTH_URL = "https://auth.dhan.co/app/generateAccessToken"
API = "https://api.dhan.co/v2"
TOKEN_FILE = STATE / "dhan_token.json"
RETRY_STATUS = {None, 429, 500, 502, 503, 504}


class TokenError(Exception):
    """No working token: PIN/TOTP missing or refused, or a static token expired."""


class DailyLimit(Exception):
    """Dhan's 100,000-calls-a-day limit is close; wait for the next IST day."""


def _save_token(token, expiry):
    STATE.mkdir(parents=True, exist_ok=True)
    tmp = TOKEN_FILE.with_suffix(".tmp")
    tmp.write_text(json.dumps({"accessToken": token, "expiry": expiry,
                               "generatedAt": dt.datetime.now(IST).isoformat(timespec="seconds")}))
    if os.name == "posix":
        os.chmod(tmp, 0o600)
    os.replace(tmp, TOKEN_FILE)


def _parse_expiry(value):
    """Dhan's expiryTime, best effort; falls back to 23 h from now."""
    if value:
        for fmt in ("%Y-%m-%dT%H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
            try:
                t = dt.datetime.strptime(str(value)[:26], fmt)
                return (t if t.tzinfo else t.replace(tzinfo=IST)).isoformat(timespec="seconds")
            except ValueError:
                continue
    return (dt.datetime.now(IST) + dt.timedelta(hours=23)).isoformat(timespec="seconds")


def totp_configured():
    return bool(ENV.get("DHAN_PIN") and ENV.get("DHAN_TOTP_SECRET"))


def generate_token():
    """PIN + the current TOTP code -> a new 24-hour token. Returns its expiry (ISO text)."""
    secret = need("DHAN_TOTP_SECRET").replace(" ", "").upper()
    try:
        pyotp.TOTP(secret).now()
    except (ValueError, TypeError):                 # binascii.Error is a ValueError
        raise TokenError("DHAN_TOTP_SECRET in .env is not a TOTP secret (it should be letters A-Z and "
                         "digits 2-7, as Dhan showed it when you set TOTP up)") from None
    pin = need("DHAN_PIN")
    if not (pin.isdigit() and len(pin) == 6):
        raise TokenError("DHAN_PIN in .env should be your 6-digit Dhan PIN")
    last = None
    for attempt in range(2):                     # a code generated at the end of its 30 s window can lapse
        params = {"dhanClientId": client_id(), "pin": need("DHAN_PIN"), "totp": pyotp.TOTP(secret).now()}
        try:
            r = requests.post(AUTH_URL, params=params, timeout=30)
            body = r.json() if r.headers.get("content-type", "").startswith("application/json") else {}
        except (requests.RequestException, ValueError) as e:
            last = f"{type(e).__name__}"
        else:
            token = body.get("accessToken")
            if r.status_code == 200 and token:
                expiry = _parse_expiry(body.get("expiryTime"))
                _save_token(token, expiry)
                return expiry
            last = f"HTTP {r.status_code}: {body.get('errorMessage') or body.get('message') or 'no accessToken in answer'}"
        if attempt == 0:
            time.sleep(31)
    raise TokenError(f"Dhan refused the PIN/TOTP login ({last}). Check DHAN_PIN and DHAN_TOTP_SECRET in .env")


def current_token(force_new=False):
    """A usable token: today's saved one, else a fresh one by TOTP, else DHAN_ACCESS_TOKEN from .env."""
    if not force_new and TOKEN_FILE.exists():
        saved = json.loads(TOKEN_FILE.read_text())
        if dt.datetime.fromisoformat(saved["expiry"]) - dt.datetime.now(IST) > dt.timedelta(minutes=30):
            return saved["accessToken"]
    if totp_configured():
        generate_token()
        return json.loads(TOKEN_FILE.read_text())["accessToken"]
    if ENV.get("DHAN_ACCESS_TOKEN") and not force_new:
        return ENV["DHAN_ACCESS_TOKEN"]
    raise TokenError("No Dhan token: set DHAN_PIN and DHAN_TOTP_SECRET (or DHAN_ACCESS_TOKEN) in .env")


class Dhan:
    """Thread-safe Dhan client: one HTTP session per thread, a shared rate limit, the daily cap,
    and a new token (by TOTP) when Dhan answers 401/403."""

    def __init__(self, calls_already_today=0):
        self.lock = threading.Lock()
        self.local = threading.local()
        self.token = current_token()
        self.next_slot = 0.0
        self.calls = calls_already_today

    def _session(self):
        if not hasattr(self.local, "s"):
            self.local.s = requests.Session()
        return self.local.s

    def _wait_turn(self):
        with self.lock:
            if self.calls >= S.DAILY_CALL_LIMIT:
                raise DailyLimit(f"{self.calls} Dhan calls today")
            now = time.monotonic()
            slot = max(now, self.next_slot)
            self.next_slot = slot + 1.0 / S.MAX_CALLS_PER_SECOND
            self.calls += 1
        time.sleep(max(0.0, slot - now))

    def _refresh(self, used):
        with self.lock:
            if self.token != used:               # another thread already renewed it
                return
            if not totp_configured():
                raise TokenError("Dhan token expired and no PIN/TOTP is set to renew it")
            self.token = current_token(force_new=True)

    def post(self, path, payload, retries=3, retry_504=True):
        """Returns (status, json_or_None, seconds, error_text). status None = network error.
        A 504 is Dhan's gateway cutting the call at 30 s; with retry_504=False it comes straight
        back so the caller can split its window."""
        renewed = False
        for attempt in range(1, retries + 1):
            self._wait_turn()
            token = self.token
            headers = {"Accept": "application/json", "Content-Type": "application/json",
                       "access-token": token, "client-id": client_id()}
            t0 = time.monotonic()
            try:
                r = self._session().post(f"{API}{path}", json=payload, headers=headers, timeout=120)
                status, text = r.status_code, r.text
            except requests.RequestException as e:
                r, status, text = None, None, f"{type(e).__name__}"
            took = time.monotonic() - t0
            if status in (401, 403) and not renewed:
                self._refresh(token)
                renewed = True
                continue
            if status in (401, 403):
                raise TokenError(f"Dhan answered HTTP {status} even with a fresh token")
            if status == 504 and not retry_504:
                return status, None, took, "gateway timeout"
            if status in RETRY_STATUS and attempt < retries:
                time.sleep(5 * attempt)
                continue
            body = None
            if status == 200:
                try:
                    body = r.json()
                except ValueError:
                    status, text = None, "answer was not JSON"
            return status, body, took, "" if status == 200 else text[:200]
        return status, None, took, text[:200]
